<?php $this->layout('default'); use Moves\Services\CmsAdmins as A; use Moves\Support\CmsView as V; $roles = []; foreach (A::roles() as $r) { $roles[$r['id']] = $r['name']; } ?>
<form class="cms-card" method="post" action="/acao/admin-grant"><h2>Conceder acesso</h2><p><small>A pessoa precisa ter conta ativa no Realizze e entra com a mesma senha.</small></p><?= V::csrf() ?><div class="cms-form-grid"><?= V::field('E-mail', 'email', '', ['type' => 'email', 'required' => true]) ?><?= V::field('Papel', 'role_id', '', ['type' => 'select', 'choices' => $roles]) ?></div><button class="cms-btn-primary">Conceder</button></form>
<div class="cms-card"><div class="cms-table-wrap"><table><thead><tr><th>Administrador</th><th>Papel e situação</th></tr></thead><tbody><?php foreach (A::listing() as $a): ?><tr><td><?= V::e(trim($a['first_name'] . ' ' . $a['last_name'])) ?><br><small><?= V::e($a['email']) ?></small></td><td><form class="cms-filters" method="post" action="/acao/admin-update" style="margin:0"><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $a['id'] ?>"><div class="cms-field"><label>Papel<select name="role_id"><?php foreach ($roles as $rid => $rname): ?><option value="<?= (int) $rid ?>"<?= (int) $rid === (int) $a['role_id'] ? ' selected' : '' ?>><?= V::e($rname) ?></option><?php endforeach; ?></select></label></div><div class="cms-field"><label>Situação<select name="status"><option value="active"<?= $a['status'] === 'active' ? ' selected' : '' ?>>Ativo</option><option value="inactive"<?= $a['status'] === 'inactive' ? ' selected' : '' ?>>Inativo</option></select></label></div><button class="cms-btn">Salvar</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
